and
\begin{align*}
    \alpha
    (
        -
        \vec w
        +
        (K-1)\vec 1
        -
        K
        \vec m
    )
    &
    =
    -
    \left(
        \vec w
        -
        \frac{K-1}{2}
        \vec 1
        +
        K
        \vec m
