    \centering

    \caption{(a) Example of a noiseless quantum-local (QL) circuit. A QL circuit $\Lambda$ consists of layers of locally reversible local channel gates, local measurements, global classical processing of measurement outcomes and feedback applied in the form of local unitary operators. (b) Specific instance of a noisy QL circuit with a specific pattern of qudit ($N_{i}$) and measurement ($\mu$) noise inserted between layers.}
    \label{fig:noisy-channel}
\end{figure}

Given a QL circuit $\Lambda$, we can define parametrized classes of noisy realizations of $\Lambda$, $\Lambda^{(\mathbb{N}_{\tau}, \mathbb{M}_{\zeta})}$. Here, $\mathbb{N}_{\tau}$ is a class of qudit noise, as given in Definition~\ref{def:noise-class}, and $\mathbb{M}_{\zeta}$ is a class of measurement error distributions. A specific noisy circuit $\Lambda^{\mathcal{N}}$ is an element of the class $\Lambda^{(\mathbb{N}_{\tau}, \mathbb{M}_{\zeta})}$, $\Lambda^{\mathcal{N}} \in \Lambda^{(\mathbb{N}_{\tau}, \mathbb{M}_{\zeta})}$, if each layer of qudit noise $\mathcal{N}_{i} \in \mathbb{N}_{\tau}$ and each distribution of measurement errors $\left\{ \mu , \pr(\mu) \right\}_{\mu} \in \mathbb{M}_{\zeta}$. In this work we only consider local stochastic measurement noise, where $\mathbb{M}_{\zeta}$ is the set of measurement error distributions $\left\{ \mu , \pr(\mu) \right\}_{\mu}$ such that for all $\left\{ \mu , \pr(\mu) \right\}_{\mu} \in \mathbb{M}_{\zeta}$, the probability distribution over the supports of $\mu$,
\begin{equation}
    \label{eq:local-stochastic-meas}
    \pr(A) = \sum_{\mu : \supp \mu = A} \pr(\mu) ,
\end{equation}
is $\zeta$-bounded as stated in Definition~\ref{def:tau-bound}.

\subsection{Fault tolerant quantum phases} \label{ft-phase-defs}

Given a convex set of states $\Sigma$ and a noise channel $\mathcal{N}$ acting on states $\rho \in \Sigma$, we wish to quantify whether information encoded in $\Sigma$ is preserved or corrupted by $\mathcal{N}$. To do so, we will introduce a recovery channel $\mathcal{R}$ associated with $\Sigma$, which we will use as an information-theoretic tool to assess whether recovery of information from a corrupted state is possible.
\begin{definition}
\label{def:recovery-channel}
    A quantum channel $\mathcal{R}$ is a recovery channel for the convex set of states $\Sigma$ and decoding map $\mathcal{D}$ if the following conditions hold.
    \begin{enumerate}
        \item For all states $\rho \in \mathbb{S}(\mathcal{H})$, $\mathcal{R}(\rho) \in \Sigma$.
        \item For all states $\rho \in \Sigma$, $\mathcal{D} \circ \mathcal{R} (\rho) \approx \mathcal{D}(\rho)$.
    \end{enumerate}
\end{definition}
We will place no restrictions on whether $\mathcal{R}$ is realizable with a shallow QL circuit or not, and we will always assume it is noiseless. Also, many $\mathcal{R}$ may exist for a given $\Sigma$ and may output different recovered states $\mathcal{R} \circ \mathcal{N} (\rho)$ when one attempts to undo the action of $\mathcal{N}$ on a state $\rho \in \Sigma$. We can quantify the effectiveness of a given recovery channel $\mathcal{R}$ against some noise channel $\mathcal{N}$ using the trace distance $\norm{\mathcal{D}(\rho) - \mathcal{D} \circ \mathcal{R} \circ \mathcal{N}(\rho)}_{1}$. A useful diagnostic is whether $\mathcal{N}$ is $\mathcal{R}$-recoverable, as defined below.
\begin{definition}
\label{def:recoverable}
    A quantum channel $\mathcal{N}$ acting on a convex set of states $\Sigma$ with decoding map $\mathcal{D}$ is $\mathcal{R}$-recoverable if
    \begin{equation}
        \label{eq:recoverable-channel}
        \sup_{\left\{\rho \in \Sigma\right\}} \norm{\mathcal{D}(\rho) - \mathcal{D} \circ \mathcal{R} \circ \mathcal{N}(\rho)}_{1} = 1/\Omega(\poly(n)) .
    \end{equation}
    We say that a class of noise $\mathbb{N}_{\tau}$ is $\mathcal{R}$-recoverable if every $\mathcal{N} \in \mathbb{N}_{\tau}$ is $\mathcal{R}$-recoverable.
\end{definition}
If $\mathcal{N}$ is $\mathcal{R}$-recoverable, then $\mathcal{D} \circ \mathcal{R} \circ \mathcal{N} (\rho) \approx \mathcal{D}(\rho)$ for all $\rho \in \Sigma$.
We now state the definition of fault tolerance which we use throughout this work.
\begin{definition}[Fault tolerant circuit]
\label{def:ft-channel}
    A quantum circuit $\Lambda : \Sigma_{1} \rightarrow \Sigma_{2}$ is fault tolerant, given decoding map $\mathcal{D}_{2}$ for $\Sigma_{2}$, against a class of noise $(\mathbb{N}_{\tau}, \mathbb{M}_{\zeta})$ if there exist critical noise strengths $\tau^{\star},\zeta^{\star} > 0$ independent of the system size $n$ and a continuous function $\eta(\tau,\zeta)$ with $\eta(0,0) = 0$ such that for all $\tau < \tau^{\star}$, $\zeta < \zeta^{\star}$, and $\mathcal{N} \in (\mathbb{N}_{\tau}, \mathbb{M}_{\zeta})$, the following conditions hold.
    \begin{enumerate}
        \item There exists a channel $\widetilde{\mathcal{N}} \in \mathbb{N}_{\eta}$, where $\eta = \eta(\tau,\zeta)$, such that $\Lambda^{\mathcal{N}} (\rho_1) \approx \widetilde{\mathcal{N}} \circ \Lambda (\rho_1)$ for all $\rho_1 \in \Sigma_{1}$.
        \item There exists a recovery channel $\mathcal{R}_{2}$ for $\Sigma_{2}$ such that $\widetilde{\mathcal{N}}$ is $\mathcal{R}_{2}$-recoverable for all $\mathcal{N} \in (\mathbb{N}_{\tau}, \mathbb{M}_{\zeta})$.
    \end{enumerate}
\end{definition}

In property 1 of Definition~\ref{def:ft-channel}, the residual noise channel $\widetilde{\mathcal{N}}$ may depend on $\Lambda$ and $\mathcal{N}$ but is independent of the state $\rho_1 \in \Sigma_{1}$ which $\Lambda^{\mathcal{N}}$ is applied to. The requirement that $\eta(\tau,\zeta)$ is continuous ensures that the residual noise grows in a controllable way when propagated through the circuit $\Lambda$. Property 2 then ensures logical information transferred by $\Lambda$ will be recovered successfully with high probability. For $\rho_{2} \approx \Lambda (\rho_1)$, these properties imply
\begin{align}
    \label{eq:ft-implications}
    \widetilde{\mathcal{N}} \circ \Lambda (\rho_1) \approx \widetilde{\mathcal{N}}(\rho_{2}) \quad &\text{(property 1)} \\
    \mathcal{D}_{2}(\rho_{2}) \approx \mathcal{D}_{2} \circ \mathcal{R}_{2} \circ \Lambda^{\mathcal{N}} (\rho_1) \quad &\text{(property 2)} \nonumber
\end{align}
as shown in Appendix~\ref{short-proofs}.
Also, the composition of two fault tolerant channels is fault tolerant, as stated by the following lemma and proven in Appendix~\ref{short-proofs}.

\begin{lemma}
\label{lemma:ft-composition}
    Suppose $\Lambda_{1} : \Sigma_{1} \rightarrow \Sigma_{2}$ and $\Lambda_{2} : \Sigma_{2} \rightarrow \Sigma_{3}$ are both fault tolerant, given decoding maps $\mathcal{D}_{2}$ for $\Sigma_{2}$ and $\mathcal{D}_{3}$ for $\Sigma_{3}$, against the class $(\mathbb{N}_{\tau}, \mathbb{M}_{\zeta})$, with minimum critical noise strengths $\tau^{\star}$ and $\zeta^{\star}$ for both channels. Then, the channel $\Lambda_{2} \circ \Lambda_{1} : \Sigma_{1} \rightarrow \Sigma_{3}$ is fault tolerant, given $\mathcal{D}_{3}$, against $(\mathbb{N}_{\tau}, \mathbb{M}_{\zeta})$ with modified critical noise strengths inferred from $\zeta < \zeta^{\star}$ and $\tau + \eta_{1} < \tau^{\star}$, where $\eta_{1} = \eta_{1}(\tau,\zeta)$ is the residual noise strength for $\Lambda_{1}$ given in Definition~\ref{def:ft-channel}.
\end{lemma}

Definition~\ref{def:ft-channel} may be used to establish a partial order on convex sets of states based on the ability to fault tolerantly transfer information from one convex set to another. We say that $\Sigma_{1} \succeq \Sigma_{2}$ with respect to the class of noise $(\mathbb{N}_{\tau}, \mathbb{M}_{\zeta})$ if there exists an $(r,\ell)$ QL circuit $\Lambda$ with $r\ell = O(\polylog(n))$ such that for all $\rho_{1} \in \Sigma_{1}$,
\begin{equation}
    \Lambda(\rho_{1}) \approx \rho_{2} \in \Sigma_{2} , \quad \mathcal{D}_{2} \circ \Lambda (\rho_{1}) \approx \mathcal{D}_{1} (\rho_{1}) ,
\end{equation}
and $\Lambda : \Sigma_{1} \rightarrow \Sigma_{2}$ is fault tolerant against $(\mathbb{N}_{\tau}, \mathbb{M}_{\zeta})$ given $\mathcal{D}_{2}$.
We may then define fault tolerant phase equivalence as the case when this information transfer is reversible.
\begin{definition}[FTQL phases]
\label{def:ft-phase-equivalence}
    Two convex sets of states $\Sigma_{1}$ and $\Sigma_{2}$ are in the same fault tolerant phase (FTQL phase) with respect to decoding maps $\mathcal{D}_{1}$ and $\mathcal{D}_{2}$ and the noise class $(\mathbb{N}_{\tau}, \mathbb{M}_{\zeta})$, $\Sigma_{1} \sim \Sigma_{2}$, if for $i=1,2$ there exists an $(r_{i},\ell_{i})$ quantum-local circuit $\Lambda_{i}$ with $r_i \ell_i = O(\polylog(n))$, such that
    \begin{enumerate}
        \item $\Lambda_{1}$ and $\Lambda_{2}$ reverse each other, meaning $\Lambda_{1} : \Sigma_{1} \rightarrow \Sigma_{2}$, $\Lambda_{2} : \Sigma_{2} \rightarrow \Sigma_{1}$, and Eq.~(\ref{eq:decoding-equivalence}) is satisfied,
        \item $\Lambda_{1}$ and $\Lambda_{2}$ are both fault tolerant for $(\mathbb{N}_{\tau}, \mathbb{M}_{\zeta})$.
    \end{enumerate}
\end{definition}

Definition~\ref{def:ft-phase-equivalence} essentially states that $\Sigma_{1}$ and $\Sigma_{2}$ are in the same phase if one can fault tolerantly transfer information from $\Sigma_{1}$ to $\Sigma_{2}$ and transfer the same information back from $\Sigma_{2}$ to $\Sigma_{1}$, guaranteeing this information is preserved. In terms of the partial order discussed above, $\Sigma_{1} \sim \Sigma_{2}$ if $\Sigma_{1} \succeq \Sigma_{2}$, $\Sigma_{2} \succeq \Sigma_{1}$, and $\Lambda_{1}$ and $\Lambda_{2}$ reverse each other. As discussed in Section~\ref{encoded-info}, a necessary condition for $\Sigma_{1} \sim \Sigma_{2}$ is that they encode the same information $\Omega$. Because of this, we will generally discuss phase equivalence of convex sets $\Sigma$ with respect to a specific set of encoded information $\Omega$, as two convex sets are always in different phases otherwise.

We comment that Definition~\ref{def:ft-phase-equivalence} is a valid equivalence relation as it is reflexive, symmetric, and transitive. Symmetry follows by construction, transitivity is proven in Lemma~\ref{lemma:ft-composition}, and reflexivity follows by defining the identity channel, $\mathbb{I}$, as a QL circuit with zero gates and zero layers. Since there are no locations where noise can be inserted in $\mathbb{I}$, any noisy realization $\mathbb{I}^{\mathcal{N}} = \mathbb{I}$ and it is always fault tolerant by definition. Therefore, any convex set $\Sigma$ is fault tolerantly connected to itself by $\mathbb{I}$. 
Lastly, one may see similarities between Definition~\ref{def:ft-phase-equivalence} and code switching in QEC. We will elaborate on these similarities and other properties in Section~\ref{ft-phase-properties}.

\subsection{Equivalence of individual states} \label{ft-state-prep}

If one chooses $\Sigma = \{\rho\}$ to be a single state, then every $\Omega = \mathcal{D} \left[ \Sigma \right]$ contains a single element. Definition~\ref{def:ft-phase-equivalence} then reduces to an equivalence relation between individual states. The recovery channel $\mathcal{R} (\cdot) = \rho \Tr\left [\cdot \right]$ will return $\rho$ irrespective of the state it is applied to, meaning property 2 of Definition~\ref{def:ft-channel} holds for any circuit $\Lambda$ connecting states $\rho_{1}$ and $\rho_{2}$. Therefore, FTQL state equivalence concerns whether there exist shallow QL circuits connecting $\rho_{1}$ and $\rho_{2}$ where noise does not propagate uncontrollably, specifically whether property 1 of Definition~\ref{def:ft-channel} is satisfied. State equivalence is similar to the noiseless phase classifications given by Definitions~\ref{def:lc-phase} and~\ref{def:ql-phase} and highlights the difference between state preparation, which depends only on equivalence between states, and transfer of encoded information, which depends on equivalence between convex sets of states. Equivalence between two states $\rho_{1} \in \Sigma_{1}$ and $\rho_{2} \in \Sigma_{2}$ does not necessarily imply the two convex sets $\Sigma_{1}$ and $\Sigma_{2}$ are equivalent. Even if one can prepare individual states which span $\Sigma_{2}$ from states in $\Sigma_{1}$, if the preparation methods differ one cannot necessarily prepare an arbitrary state in $\Sigma_{2}$ from some state in $\Sigma_{1}$. For example, in Section~\ref{q-form-tc}, we will show that the $\dyad{\overline{0}}{\overline{0}}^{\otimes k}$ state of the 4D toric code is equivalent to the product state, $\dyad{0}{0}^{\otimes n}$. However, we show in Section~\ref{trivial-phases} that the code space of any topological code, such as the 4D toric code, is not in the same phase as any set of $k$ unencoded qubits. We will study instances and properties of encoded information transfer in Sections~\ref{ft-phase-properties} and~\ref{cc-phases} and of state preparation in Sections~\ref{robust-meas-feedback} and~\ref{non-robust-circuits}.

